# -*- coding: utf-8 -*-
"""Stage 3 merge for report 65 (Rabit: Daily Routine Planner, GARJ APLICATIVOS LTDA)."""
import json
C = {x["id"]: x for x in json.load(open("Tools/prd_ledger/canonical.json"))}
def ext(cid, text):
    if text not in C[cid]["statement"]: C[cid]["statement"] += text
def add(cid, section, title, statement):
    if cid in C: return
    C[cid] = dict(id=cid, title=title, statement=statement, section=section, cards=[], reports=[], merged_from=[])

add("C284", "must-never-break", "Verify the rendered price string in every storefront currency — a decimal or tier error on the paywall suppresses conversion invisibly, because nobody who closes a paywall writes a review",
    "Report 65 (Rabit, 498 reviews): four independent Brazilian reviewers, Jun–Nov 2022, report the monthly price as R$299–R$300 and one as R$600, against R$29.90 reported elsewhere — 'Excelente só corrijam o bug do preço mês que está R$ 299,00 e não 29,90' (5★); 'desinstalei por medo de sem querer assinar o plus e ter que viver de aluguel pois custa 600 reais' (5★, uninstalled); 'Cobrar 300 reais por mês pra ter acesso a coisas fúteis' (3★); two of the four rated 5★ while reporting it as a bug; PAY_PRICE_BUG 4 (0.80%, mean 4.25) — 'high-severity, low-volume': in the storefront holding 77.2% of the app's 5,366 ratings a 10× display error 'would suppress conversion invisibly'; F4: check the App Store Connect BRL tier and the paywall's own string formatting — research #1, 'Highest-value single check in this list'. Related: [[C113]] (one stable, disclosed price), [[C092]] (regional pricing).")

ext("C039", " Report 65 (Rabit): the ledger's clearest reminder regression — REM_FAIL 66 (13.25%, mean 2.91), 10.8% of launch-era reviews, 0.8% for the next 25 months, then 45.7% of everything written from Nov 2023 to Sep 2026 and still open at the last review; 14 reviewers (2.81%) report the app is absent from iOS Settings → Notifications altogether, across iPhone and iPad, seven storefronts and five languages, after reinstalls — 'almost certainly a missing or failing UNUserNotificationCenter authorization request'; 'Qual o sentido de fazer um app de habitos e nao ter notificação?'; 15 of 66 are 4★ and 9 are 5★; REM_GOOD (a perfect 5.00) fell 8.1% → 0.8%; the loop a reviewer described — cue (notification), routine, reward (the tree) — loses its first step; three abandoned lifetime / subscription purchases, 10 of 49 payers, three refunds; F1: confirm the authorization request on a current device before anything else.")
ext("C008", " Report 65 (Rabit): notifications were never gated, yet a reviewer asks whether they were — when the reminder breaks for everyone, free users read it as a paywall.")
ext("C065", " Report 65 (Rabit): 49 self-stated payers average 2.061 against 3.677 (27 of 49 at 1★, 3× over-represented), and the 1★ band's top theme is PAY_PAID (29.67%) — 'the one-star band is mostly composed of (a) people who could not get into the app at all and (b) people who paid and could not get what they paid for. Neither group is a pricing problem'; payer complaints peak in 2023, the cap year; only 2 say paid was worth it against 16 who say not.")
ext("C033", " Report 65 (Rabit): PAY_ENTITLE 9 (1.81%, mean 1.56) — 100% payers, Sep 2021 → Mar 2026: 'Fiz a assinatura do plano plus anual e o app não reconhece!'; a subscriber still capped at five habits; a buyer's to-do list locked; lifetime charged but 'O app consta como se eu não tivesse o pacote'; ads and 'upgrade to premium' prompts after paying; a new phone offered only a new plan; an account 'não existe' after reinstall; F2: audit fresh install, new device, reinstall and Android→iOS, and make Restore Purchases reachable.")
ext("C271", " Report 65 (Rabit): an Android build exists but does not bridge — 'a opção de restaurar só acontece de celular androide para androide'; an Android→iPhone payer could not restore and got no reply; another could not find the sign-in button on iPhone.")
ext("C036", " Report 65 (Rabit): SUP_SILENT 5 — every one 1★ and every one a payer ('Mandei dois e-mails solicitando o estorno da compra, mas até o momento não deram retorno'; 'ninguém responde… Um descaso total!') — each a problem one reply would have converted; F3: 'the cheapest rating repair available'.")
ext("C059", " Report 65 (Rabit): a first-run block (12 of 26 reviews in 16–31 Jul 2021, mean 1.42) was fixed within days and reviewers came back — 'CORRIGIRAM O BUG — OBRIGADAAAA! Amei!' (DEV_FIX 3, mean 5.00) — 'the corpus's proof that fast fixes are visibly rewarded'; the Apr–Nov 2022 crash wave (13 of 67, eight payers) was not visibly fixed and one reviewer could not open the app for seven months.")
ext("C071", " Report 65 (Rabit): in-app copy still said 'start your 2024 year strong' in Feb 2025 and the purchase screen still said 2024 in Sep 2026 ('Poderiam verificar o anúncio de compra que está em 2024?'); 'Tinha tudo pra ser do topo de app de hábitos mas não atualiza' (DEV_STALE 5, all 2025–2026); review volume 120 → 106 → 67 → 30 → 12 per year with the mean not recovering — 'attrition, not repair'; F10: 'the clearest public signal that the app is abandoned' is a trivial string.")
ext("C007", " Report 65 (Rabit): the free tier without a 3-habit cap was the positioning — PAY_FREE_OK 48 (9.64%, mean 4.88: 'you can log more than three habits for the free version'; 'te deja añadir más de 3 hábitos en su versión gratuita') — then a cap reported at 3, 4, 5 and 6 in different months of 2023 (PAY_FREE_LIMIT 34, 6.83%, mean 2.00; 26 of 99 reviews in Jan–Nov 2023, mean 1.85) — 'the limit was moved repeatedly rather than set once'; PAY_FREE_OK 15.3% → 2.2% as PAY_FREE_LIMIT 1.2% → 28.3% — 'the same axis, inverted'; two users in 2020 had pleaded in advance not to be capped at three.")
ext("C001", " Report 65 (Rabit): premium launched in Nov 2020 by taking a capability that already existed (marking the previous day); in 2023 the to-do list and backup moved behind the paywall; PAY_REGRESS 21 (4.22%, mean 1.48): 'Antes o Rabit não tinha anúncios, e dava para colocar vários hábitos… Eu adorava esse app'.")
ext("C191", " Report 65 (Rabit): capping the free tier after years of generous use drove the E1/E2 cohort out — a user since 2020 uninstalled in 2023 ('antes era mejor'), another had recommended it to about 30 people ('ate eles se importarem mais em ganhar dinheiro que ajudar os outros'); COMP_WORSE 11 (mean 2.09), all Dec 2022 or later — 'The competitive position was not lost to a competitor's feature. It was given away'.")
ext("C104", " Report 65 (Rabit): three model changes in six years each visible in the era means — free 4.49 → optional premium 4.19 → ads + cap 2.98 → notification outage 2.98; the E2 → E3 drop of 1.21 stars coincides exactly with ads plus the cap.")
